  IF NOT EXISTS (SELECT 1 FROM public.viva_model_answers WHERE id='d3105fd5-afb1-4a27-b9d7-ccacdd7759ab'::uuid AND topic_title='Endocrine Emergencies in ICU' AND model_answer='Diabetic Ketoacidosis (DKA) is an endocrine emergency characterized by the biochemical triad of hyperglycaemia (usually >11 mmol/L), ketonaemia (capillary ketones >3.0 mmol/L or ketonuria 2+), and a metabolic acidosis (venous pH <7.3 or bicarbonate <15 mmol/L). It results from relative or absolute insulin deficiency combined with an excess of counter-regulatory hormones (glucagon, cortisol, catecholamines), leading to uninhibited lipolysis and ketone body production (beta-hydroxybutyrate).

Clinical management prioritizes fluid resuscitation, typically starting with 1 litre of 0.9% Sodium Chloride over the first hour; however, caution is required in young patients to avoid cerebral oedema and in the elderly to avoid fluid overload. Fixed-rate intravenous insulin infusion (FRIII) is commenced at 0.1 units/kg/hour. A critical clinical pearl is the early replacement of potassium; despite a total body potassium deficit, plasma levels may initially appear normal or high due to the extracellular shift in acidosis. If serum K+ is between 3.5 and 5.5 mmol/L, 40 mmol/L should be added to each litre of fluid. 

Vital monitoring includes hourly capillary blood glucose and ketones, with a target ketone reduction of 0.5 mmol/L/hr. Common pitfalls include the premature cessation of long-acting basal insulin and the development of hyperchloraemic metabolic acidosis due to excessive 0.9% saline administration, which can mimic non-resolution of DKA. For adults following JBDS, biochemical resolution requires blood ketones below 0.6 mmol/L and venous pH above 7.3. The decision to transition to a subcutaneous insulin regimen also takes account of whether the patient can eat and drink. Follow the local diabetes pathway for safe IV-to-subcutaneous overlap. Source: https://abcd.care/sites/default/files/site_uploads/JBDS_Guidelines_Current/JBDS_02_Single_page_pathway_March_2023.pdf' AND high_yield_points='["Biochemical triad: Hyperglycaemia, Ketonemia, Metabolic Acidosis.","Fluid resuscitation is the priority (1L/1hr initially).","Individualise potassium replacement using serial levels, renal function, urine output and the adult JBDS pathway.","Fixed-rate insulin infusion at 0.1 units/kg/hour.","Continue long-acting basal insulin (Lantus/Levemir).","Adult JBDS biochemical resolution requires blood ketones <0.6 mmol/L and venous pH >7.3. Bicarbonate and oral intake are not additional biochemical criteria."]'::jsonb) THEN
    UPDATE public.viva_model_answers SET model_answer='Diabetic Ketoacidosis (DKA) is an endocrine emergency characterized by the biochemical triad of hyperglycaemia (usually >11 mmol/L), ketonaemia (capillary ketones >3.0 mmol/L or ketonuria 2+), and a metabolic acidosis (venous pH <7.3 or bicarbonate <15 mmol/L). It results from relative or absolute insulin deficiency combined with an excess of counter-regulatory hormones (glucagon, cortisol, catecholamines), leading to uninhibited lipolysis and ketone body production (beta-hydroxybutyrate).

Clinical management prioritizes fluid resuscitation, typically starting with 1 litre of 0.9% Sodium Chloride over the first hour; however, caution is required in young patients to avoid cerebral oedema and in the elderly to avoid fluid overload. Fixed-rate intravenous insulin infusion (FRIII) is commenced at 0.1 units/kg/hour. A critical clinical pearl is the early replacement of potassium; despite a total body potassium deficit, plasma levels may initially appear normal or high due to the extracellular shift in acidosis. If serum K+ is between 3.5 and 5.5 mmol/L, 40 mmol/L should be added to each litre of fluid. 

Vital monitoring includes hourly capillary blood glucose and ketones, with a target ketone reduction of 0.5 mmol/L/hr. Common pitfalls include the premature cessation of long-acting basal insulin and the development of hyperchloraemic metabolic acidosis due to excessive 0.9% saline administration, which can mimic non-resolution of DKA. For adults following JBDS, biochemical resolution requires blood ketones below 0.6 mmol/L and venous pH above 7.3. The decision to transition to a subcutaneous insulin regimen also takes account of whether the patient can eat and drink. Follow the local diabetes pathway for safe IV-to-subcutaneous overlap. Source: https://abcd.care/sites/default/files/site_uploads/JBDS_Guidelines_Current/JBDS_02_Single_page_pathway_March_2023.pdf', high_yield_points='["Biochemical triad: Hyperglycaemia, Ketonemia, Metabolic Acidosis.","Fluid resuscitation is the priority (1L/1hr initially).","Individualise potassium replacement using serial levels, renal function, urine output and the adult JBDS pathway.","Fixed-rate insulin infusion at 0.1 units/kg/hour.","Continue long-acting basal insulin (Lantus/Levemir).","Adult JBDS biochemical resolution requires blood ketones <0.6 mmol/L and venous pH >7.3. Bicarbonate and oral intake are not additional biochemical criteria."]'::jsonb WHERE id='d3105fd5-afb1-4a27-b9d7-ccacdd7759ab'::uuid AND topic_title='Endocrine Emergencies in ICU' AND model_answer='Diabetic Ketoacidosis (DKA) is an endocrine emergency characterized by the biochemical triad of hyperglycaemia (usually >11 mmol/L), ketonaemia (capillary ketones >3.0 mmol/L or ketonuria 2+), and a metabolic acidosis (venous pH <7.3 or bicarbonate <15 mmol/L). It results from relative or absolute insulin deficiency combined with an excess of counter-regulatory hormones (glucagon, cortisol, catecholamines), leading to uninhibited lipolysis and ketone body production (beta-hydroxybutyrate).

Clinical management prioritizes fluid resuscitation, typically starting with 1 litre of 0.9% Sodium Chloride over the first hour; however, caution is required in young patients to avoid cerebral oedema and in the elderly to avoid fluid overload. Fixed-rate intravenous insulin infusion (FRIII) is commenced at 0.1 units/kg/hour. A critical clinical pearl is the early replacement of potassium; despite a total body potassium deficit, plasma levels may initially appear normal or high due to the extracellular shift in acidosis. If serum K+ is between 3.5 and 5.5 mmol/L, 40 mmol/L should be added to each litre of fluid. 

Vital monitoring includes hourly capillary blood glucose and ketones, with a target ketone reduction of 0.5 mmol/L/hr. Common pitfalls include the premature cessation of long-acting basal insulin and the development of hyperchloraemic metabolic acidosis due to excessive 0.9% saline administration, which can mimic non-resolution of DKA. DKA is considered resolved when ketones are <0.6 mmol/L, venous pH is >7.3, and the patient is able to eat and drink.' AND high_yield_points='["Biochemical triad: Hyperglycaemia, Ketonemia, Metabolic Acidosis.","Fluid resuscitation is the priority (1L/1hr initially).","Potassium replacement starts even if plasma K+ is normal.","Fixed-rate insulin infusion at 0.1 units/kg/hour.","Continue long-acting basal insulin (Lantus/Levemir).","Criteria for resolution: pH >7.3, Bicarb >18, Ketones <0.6."]'::jsonb;
    IF NOT FOUND THEN RAISE EXCEPTION 'Viva changed during clinical review: %', 'd3105fd5-afb1-4a27-b9d7-ccacdd7759ab'; END IF;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.viva_model_answers WHERE id='8c2cdf64-b721-4b0c-85d8-eead53167095'::uuid AND topic_title='Anaesthesia for Emergency Surgery' AND model_answer='Anaesthetising an unstable patient for an emergency laparotomy requires a modified Rapid Sequence Induction (RSI) to mitigate the risks of aspiration and cardiovascular collapse. 

Preparation is paramount: I would ensure wide-bore access, invasive monitoring (arterial line) prior to induction if time permits, and ''vasopressors at the pump'' (e.g., metaraminol or ephedrine drawn up or a noradrenaline infusion running). Pre-oxygenation should be maximal, ideally using head-up positioning and high-flow nasal oxygen (HFNO) to extend the apnoeic window.

Drug selection is tailored to the hemodynamics. In the shocked patient, I would use Ketamine (0.5-1mg/kg) or Etomidate (0.15-0.3mg/kg) due to their superior hemodynamic profiles compared to Propofol. Select a rapid-onset neuromuscular blocker according to contraindications and physiology. When rocuronium is used, reversal can form part of a planned wake-up after failed intubation if oxygenation is maintained. If oxygenation fails despite rescue attempts, declare cannot intubate, cannot oxygenate and proceed immediately to emergency front-of-neck airway with adequate neuromuscular block. Waiting for sugammadex may delay oxygenation. Source: Difficult Airway Society 2025, https://pubmed.ncbi.nlm.nih.gov/41203471/ .

The primary risk is the ''induction-to-incision'' hypotension caused by the loss of sympathetic drive and the effects of positive pressure ventilation on venous return. I would use small, titrated tidal volumes and early vasopressor support to maintain a MAP >65mmHg. If the patient has a ''difficult airway'' predicted, the risk of aspiration must be balanced against the risk of a failed airway; an awake fibreoptic intubation might be considered, though this is rare in ''Immediate'' cases.' AND high_yield_points='["Rapid Sequence Induction (RSI) components and rationale","Modification of induction agents (e.g., Ketamine over Propofol in shock)","Management of the ''can''t intubate, can''t oxygenate'' (CICO) scenario in emergency settings","Aggressive hemodynamic support (vasopressor at the pump)","Pre-oxygenation techniques (NODDES/HFNO)"]'::jsonb) THEN
    UPDATE public.viva_model_answers SET model_answer='Anaesthetising an unstable patient for an emergency laparotomy requires a modified Rapid Sequence Induction (RSI) to mitigate the risks of aspiration and cardiovascular collapse. 

Preparation is paramount: I would ensure wide-bore access, invasive monitoring (arterial line) prior to induction if time permits, and ''vasopressors at the pump'' (e.g., metaraminol or ephedrine drawn up or a noradrenaline infusion running). Pre-oxygenation should be maximal, ideally using head-up positioning and high-flow nasal oxygen (HFNO) to extend the apnoeic window.

Drug selection is tailored to the hemodynamics. In the shocked patient, I would use Ketamine (0.5-1mg/kg) or Etomidate (0.15-0.3mg/kg) due to their superior hemodynamic profiles compared to Propofol. Select a rapid-onset neuromuscular blocker according to contraindications and physiology. When rocuronium is used, reversal can form part of a planned wake-up after failed intubation if oxygenation is maintained. If oxygenation fails despite rescue attempts, declare cannot intubate, cannot oxygenate and proceed immediately to emergency front-of-neck airway with adequate neuromuscular block. Waiting for sugammadex may delay oxygenation. Source: Difficult Airway Society 2025, https://pubmed.ncbi.nlm.nih.gov/41203471/ .

The primary risk is the ''induction-to-incision'' hypotension caused by the loss of sympathetic drive and the effects of positive pressure ventilation on venous return. I would use small, titrated tidal volumes and early vasopressor support to maintain a MAP >65mmHg. If the patient has a ''difficult airway'' predicted, the risk of aspiration must be balanced against the risk of a failed airway; an awake fibreoptic intubation might be considered, though this is rare in ''Immediate'' cases.', high_yield_points='["Rapid Sequence Induction (RSI) components and rationale","Modification of induction agents (e.g., Ketamine over Propofol in shock)","Management of the ''can''t intubate, can''t oxygenate'' (CICO) scenario in emergency settings","Aggressive hemodynamic support (vasopressor at the pump)","Pre-oxygenation techniques (NODDES/HFNO)"]'::jsonb WHERE id='8c2cdf64-b721-4b0c-85d8-eead53167095'::uuid AND topic_title='Anaesthesia for Emergency Surgery' AND model_answer='Anaesthetising an unstable patient for an emergency laparotomy requires a modified Rapid Sequence Induction (RSI) to mitigate the risks of aspiration and cardiovascular collapse. 

Preparation is paramount: I would ensure wide-bore access, invasive monitoring (arterial line) prior to induction if time permits, and ''vasopressors at the pump'' (e.g., metaraminol or ephedrine drawn up or a noradrenaline infusion running). Pre-oxygenation should be maximal, ideally using head-up positioning and high-flow nasal oxygen (HFNO) to extend the apnoeic window.

Drug selection is tailored to the hemodynamics. In the shocked patient, I would use Ketamine (0.5-1mg/kg) or Etomidate (0.15-0.3mg/kg) due to their superior hemodynamic profiles compared to Propofol. Rocuronium (1.2mg/kg) is often preferred over Suxamethonium as it avoids the potassium rise and provides a prolonged window for intubation, provided Sugammadex is available for rescue.

The primary risk is the ''induction-to-incision'' hypotension caused by the loss of sympathetic drive and the effects of positive pressure ventilation on venous return. I would use small, titrated tidal volumes and early vasopressor support to maintain a MAP >65mmHg. If the patient has a ''difficult airway'' predicted, the risk of aspiration must be balanced against the risk of a failed airway; an awake fibreoptic intubation might be considered, though this is rare in ''Immediate'' cases.' AND high_yield_points='["Rapid Sequence Induction (RSI) components and rationale","Modification of induction agents (e.g., Ketamine over Propofol in shock)","Management of the ''can''t intubate, can''t oxygenate'' (CICO) scenario in emergency settings","Aggressive hemodynamic support (vasopressor at the pump)","Pre-oxygenation techniques (NODDES/HFNO)"]'::jsonb;
    IF NOT FOUND THEN RAISE EXCEPTION 'Viva changed during clinical review: %', '8c2cdf64-b721-4b0c-85d8-eead53167095'; END IF;
  END IF;
END;
